import { Mesh, PlaneGeometry, Object3D } from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/tsl';
import { gsap } from 'gsap';
import * as primitives from '@/primitives';
import { createTextMesh } from '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {Object} assets
 * @property {string} assets.imageUrl
 * @property {Array<string|Object>} textContent
 * @property {Object} scenePlacement
 * @property {Array<number>} scenePlacement.position
 * @property {Array<number>} scenePlacement.rotation
 * @property {Array<number>} scenePlacement.scale
 * @property {Array<Object>} cinematicPrimitives
 */

/**
 * @typedef {Object} NodeContext
 * @property {function(string): THREE.Texture} textureLoader
 * @property {function(string): Promise<GLTF>} glbLoader
 * @property {Object<string, function(THREE.Object3D, any): void>} primitives
 * @property {any} fontAtlas
 */

/**
 * Creates a hero‑subhead node: a textured plane with MSDF text.
 *
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
    const root = new Object3D();

    // -------------------------------------------------
    // 1️⃣  Textured plane (background image)
    // -------------------------------------------------
    const planeGeo = new PlaneGeometry(1, 1);
    const tex = ctx.textureLoader(config.assets?.imageUrl);
    const planeMat = new MeshBasicNodeMaterial({ map: tex, transparent: true });
    const planeMesh = new Mesh(planeGeo, planeMat);
    // Preserve the image aspect ratio
    if (tex?.image?.width && tex?.image?.height) {
        const aspect = tex.image.width / tex.image.height;
        planeMesh.scale.set(aspect, 1, 1);
    }
    root.add(planeMesh);

    // -------------------------------------------------
    // 2️⃣  MSDF text (headline)
    // -------------------------------------------------
    // config.textContent may be a simple string or an array of objects; grab the first string.
    let headline = '';
    if (Array.isArray(config.textContent)) {
        const first = config.textContent[0];
        headline = typeof first === 'string' ? first : first?.text || '';
    } else if (typeof config.textContent === 'string') {
        headline = config.textContent;
    }

    const textMesh = createTextMesh({
        text: headline,
        fontAtlas: ctx.fontAtlas,
        color: config.colors?.ink ?? '#16161d',
        // rough size in scene‑units; designers tune later
        size: 0.08,
        align: 'center',
        // slight offset so it renders above the plane
        depthTest: true,
        depthWrite: false,
    });
    // Position text a bit above the plane centre
    textMesh.position.set(0, 0.6, 0.01);
    root.add(textMesh);

    // -------------------------------------------------
    // 3️⃣  Placement (position / rotation / scale)
    // -------------------------------------------------
    const pos = config.scenePlacement?.position ?? [0, 0, 0];
    const rot = config.scenePlacement?.rotation ?? [0, 0, 0];
    const scl = config.scenePlacement?.scale ?? [1, 1, 1];

    root.position.set(pos[0], pos[1], pos[2]);
    root.rotation.set(rot[0], rot[1], rot[2]);
    root.scale.set(scl[0], scl[1], scl[2]);

    // -------------------------------------------------
    // 4️⃣  Apply cinematic primitives (if any)
    // -------------------------------------------------
    if (Array.isArray(config.cinematicPrimitives)) {
        for (const prim of config.cinematicPrimitives) {
            const fn = ctx.primitives?.[prim.name];
            if (typeof fn === 'function') {
                fn(root, prim.params);
            }
        }
    }

    // -------------------------------------------------
    // 5️⃣  Event handlers placeholder
    // -------------------------------------------------
    root.userData.handlers = {};

    // -------------------------------------------------
    // 6️⃣  Cleanup
    // -------------------------------------------------
    const timelines = []; // we might push GSAP timelines here later

    root.userData.cleanup = () => {
        // dispose plane resources
        planeMat.dispose();
        planeGeo.dispose();
        if (tex && tex.dispose) tex.dispose();

        // dispose text resources
        if (textMesh) {
            if (textMesh.geometry) textMesh.geometry.dispose();
            if (textMesh.material) textMesh.material.dispose();
        }

        // kill any GSAP timelines tied to this node
        timelines.forEach((tl) => tl.kill());
    };

    return root;
}
